// Recipe -> font bytes, plus the in-memory cache the exporter draws on (§8.7.7).
//
// A project stores only the RECIPE for a custom font (which typeface, what
// size, which characters), never the generated bytes. That keeps the project
// file small, keeps font data out of a document people share, and means a
// project never carries a redistributable copy of a typeface around with it.
//
// The cost is that the bytes have to be rebuilt: on a fresh load the cache is
// empty and ensureFontData() re-runs the pipeline before an export. For Google
// fonts that is automatic. For a typeface the user supplied as a local file
// there is nothing to re-fetch, so the file has to be handed back — the UI asks
// for it rather than silently exporting a project with a font missing.
import { resolveCharset, splitBmp, migrateSets } from './charsets.js';
import { composeFont } from './compose.js';
import { encodeU8g2 } from './u8g2enc.js';

// name -> { data, stats, source, charset, key }. Module-level (not store state)
// because it is derived data, must not enter undo history, and must not be
// serialized with the project.
const cache = new Map();

// Local font files the user handed over this session, kept so a rebuild after
// an edit does not ask for the same file again. Cleared on reload with the rest.
const localFiles = new Map(); // name -> ArrayBuffer

// The last primary rasterization per font, so accepting a fallback offer (which
// changes nothing about the primary) does not rasterize the whole set again.
const primedPasses = new Map(); // name -> { key, result }

// Identifies a recipe, so an edit invalidates the cached bytes but a no-op
// re-render does not.
export const recipeKey = (r) => JSON.stringify([
  r.source?.kind, r.source?.family, r.source?.weight, r.source?.italic,
  r.size, r.threshold, setsOf(r).slice().sort(), r.customText, r.customRanges,
  r.fallback || null,
]);

// A recipe's set list, with any ids saved against the previous character-set
// model mapped onto current ones (charsets.js migrateSets). Doing it here means
// an old project rebuilds correctly on export without being opened for editing.
export const setsOf = (r) => migrateSets(r.sets || r.presets || []);

export const cachedFont = (name) => cache.get(name) || null;
export const isCached = (name, recipe) => cache.get(name)?.key === recipeKey(recipe);
export const rememberLocalFile = (name, buffer) => localFiles.set(name, buffer);
export const hasLocalFile = (name) => localFiles.has(name);
export function forgetFont(name) { cache.delete(name); localFiles.delete(name); primedPasses.delete(name); }

/**
 * Build one custom font from its recipe. Resolves to the cache entry, and
 * stores it under `name` so the exporter can find it.
 *
 * @throws when a local-file recipe has no file available this session.
 */
export async function buildFont(name, recipe, { onProgress } = {}) {
  const cps = splitBmp(resolveCharset({
    sets: setsOf(recipe), customText: recipe.customText, customRanges: recipe.customRanges,
  })).bmp;
  if (!cps.length) throw new Error(`"${name}": no characters selected`);

  const style = { weight: recipe.source.weight || 400, italic: !!recipe.source.italic };
  const buffer = recipe.source.kind === 'local' ? localFiles.get(name) : null;
  if (recipe.source.kind === 'local' && !buffer) {
    throw new Error(`"${name}": the local font file is not available in this session`);
  }

  const { glyphs, missing, font, sources, primed } = await composeFont({
    source: { kind: recipe.source.kind, family: recipe.source.family, buffer },
    fallback: recipe.fallback || null,
    size: recipe.size,
    codepoints: cps,
    style,
    threshold: recipe.threshold,
    primed: primedPasses.get(name) || null,
    onProgress,
  });
  primedPasses.set(name, primed);
  if (!glyphs.length) throw new Error(`"${name}": the typeface has none of the selected characters`);

  const enc = encodeU8g2(glyphs, font);
  const entry = {
    key: recipeKey(recipe),
    data: enc.data,
    glyphs,
    font,
    missing,
    skipped: enc.skipped,
    sources,
    // The first source is the typeface asked for; the rest filled in gaps.
    source: sources[0],
    charset: { presets: setsOf(recipe), codepoints: cps },
    stats: {
      height: font.height, ascent: font.ascent, descent: font.descent,
      glyphCount: enc.glyphCount, bytes: enc.data.length,
    },
  };
  cache.set(name, entry);
  return entry;
}

// Custom fonts in a project, as [name, recipe] pairs.
export const customFontsOf = (project) =>
  (project.fonts || []).filter((f) => f.custom).map((f) => [f.name, f.custom]);

/**
 * Make sure every custom font in the project has current bytes in the cache.
 * Returns { built, missing } — `missing` lists the fonts that could not be
 * rebuilt (local files not supplied this session), which the caller surfaces
 * instead of exporting a header with a font silently absent.
 */
export async function ensureFontData(project, { onProgress } = {}) {
  const built = [];
  const missing = [];
  for (const [name, recipe] of customFontsOf(project)) {
    if (isCached(name, recipe)) continue;
    try {
      onProgress?.({ name, phase: 'start' });
      await buildFont(name, recipe, {
        onProgress: (p) => onProgress?.({ name, phase: 'raster', ...p }),
      });
      built.push(name);
    } catch (e) {
      missing.push({ name, reason: e.message });
    }
  }
  return { built, missing };
}

// Everything codegen needs, as a plain map it can read synchronously.
export function fontDataMap(project) {
  const out = new Map();
  for (const [name, recipe] of customFontsOf(project)) {
    const hit = cache.get(name);
    if (hit && hit.key === recipeKey(recipe)) out.set(name, hit);
  }
  return out;
}
